// PlugAI project — Arduino Uno (ATmega328P)
// LCD pixel pet: 1.8" ST7735 128x160 SPI TFT, hand-written driver (no 3rd-party lib).
// Scene (portrait 128 wide x 160 tall): light-blue sky, 40 px green grass at the
// bottom, a sitting orange cat (ears, head, body, dark eyes, pink nose, cream paws),
// centred 4x-scaled 5x7 pixel text "HI" in white at the top, and the cat's tail
// swapping posture every 500 ms (sticking out to the right <-> raised upright).
//
// Wiring: SCK->D13, SDA->D11 (hardware SPI), CS->D10, DC->D9, RST->D8,
//         VCC->5V, GND->GND1, BL->5V.
// Only a 2 KB SRAM budget: no frame buffer, everything is drawn as filled rects.

#include <SPI.h>

// ---------------------------------------------------------------- pins
static const uint8_t PIN_CS  = 10;
static const uint8_t PIN_DC  = 9;
static const uint8_t PIN_RST = 8;

// ---------------------------------------------------------------- palette (RGB565)
static const uint16_t C_SKY    = 0x867D; // light blue  (~#87CEEB)
static const uint16_t C_GRASS  = 0x3666; // green       (~#30CC30)
static const uint16_t C_ORANGE = 0xFC60; // cat orange  (#FF8C00)
static const uint16_t C_WHITE  = 0xFFFF;
static const uint16_t C_EYE    = 0x2104; // dark grey   (~#202020)
static const uint16_t C_NOSE   = 0xFBB5; // pink        (~#FF77AA)
static const uint16_t C_CREAM  = 0xFF16; // cream paws  (~#FFE0B0)

static const int16_t LCD_W = 128;
static const int16_t LCD_H = 160;

// ---------------------------------------------------------------- 5x7 font
// Each glyph: 7 bytes (rows, top to bottom); low 5 bits = pixels,
// bit4 = leftmost column, bit0 = rightmost column.
static const uint8_t FONT_H[7] PROGMEM = {
  0b10001, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001
};
static const uint8_t FONT_I[7] PROGMEM = {
  0b11111, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100, 0b11111
};

// ---------------------------------------------------------------- low level
static inline void cmd(uint8_t c) {
  digitalWrite(PIN_DC, LOW);
  digitalWrite(PIN_CS, LOW);
  SPI.transfer(c);
  digitalWrite(PIN_CS, HIGH);
}

static inline void data8(uint8_t d) {
  digitalWrite(PIN_DC, HIGH);
  digitalWrite(PIN_CS, LOW);
  SPI.transfer(d);
  digitalWrite(PIN_CS, HIGH);
}

// CASET + RASET + RAMWR, leaves CS LOW and DC HIGH ready for pixel data.
static void setWindow(int16_t x0, int16_t y0, int16_t x1, int16_t y1) {
  digitalWrite(PIN_DC, LOW);
  digitalWrite(PIN_CS, LOW);
  SPI.transfer(0x2A);                       // CASET
  digitalWrite(PIN_DC, HIGH);
  SPI.transfer(0x00); SPI.transfer((uint8_t)x0);
  SPI.transfer(0x00); SPI.transfer((uint8_t)x1);

  digitalWrite(PIN_DC, LOW);
  SPI.transfer(0x2B);                       // RASET
  digitalWrite(PIN_DC, HIGH);
  SPI.transfer(0x00); SPI.transfer((uint8_t)y0);
  SPI.transfer(0x00); SPI.transfer((uint8_t)y1);

  digitalWrite(PIN_DC, LOW);
  SPI.transfer(0x2C);                       // RAMWR
  digitalWrite(PIN_DC, HIGH);
}

// Solid rectangle, clipped to the panel.
static void fillRect(int16_t x, int16_t y, int16_t w, int16_t h, uint16_t color) {
  if (w <= 0 || h <= 0) return;
  int16_t x1 = x + w - 1;
  int16_t y1 = y + h - 1;
  if (x < 0) x = 0;
  if (y < 0) y = 0;
  if (x1 > LCD_W - 1) x1 = LCD_W - 1;
  if (y1 > LCD_H - 1) y1 = LCD_H - 1;
  if (x1 < x || y1 < y) return;

  setWindow(x, y, x1, y1);

  uint8_t hi = (uint8_t)(color >> 8);
  uint8_t lo = (uint8_t)(color & 0xFF);
  uint32_t n = (uint32_t)(x1 - x + 1) * (uint32_t)(y1 - y + 1);
  for (uint32_t i = 0; i < n; i++) {
    SPI.transfer(hi);
    SPI.transfer(lo);
  }
  digitalWrite(PIN_CS, HIGH);
}

// ---------------------------------------------------------------- 4x-scaled pixel text
static void drawGlyph(const uint8_t *glyph, int16_t x, int16_t y,
                      uint8_t scale, uint16_t color) {
  for (uint8_t row = 0; row < 7; row++) {
    uint8_t bits = pgm_read_byte(glyph + row);
    for (uint8_t col = 0; col < 5; col++) {
      if (bits & (1 << (4 - col))) {
        fillRect(x + col * scale, y + row * scale, scale, scale, color);
      }
    }
  }
}

// ---------------------------------------------------------------- ST7735 init
static void lcdInit() {
  pinMode(PIN_CS, OUTPUT);
  pinMode(PIN_DC, OUTPUT);
  pinMode(PIN_RST, OUTPUT);

  digitalWrite(PIN_CS, HIGH);
  digitalWrite(PIN_DC, HIGH);

  // hardware reset pulse
  digitalWrite(PIN_RST, LOW);
  delay(20);
  digitalWrite(PIN_RST, HIGH);
  delay(120);

  cmd(0x01);                 // SWRESET
  delay(150);

  cmd(0x11);                 // SLPOUT
  delay(120);

  cmd(0x3A); data8(0x05);    // COLMOD: 16 bit / pixel (RGB565)
  delay(10);

  cmd(0x36); data8(0x00);    // MADCTL: portrait 128x160, header at the bottom
  delay(10);

  cmd(0x29);                 // DISPON
  delay(20);
}

// ---------------------------------------------------------------- scene
static void drawTextHi() {
  drawGlyph(FONT_H, 40, 12, 4, C_WHITE);   // H : x40..59
  drawGlyph(FONT_I, 64, 12, 4, C_WHITE);   // I : x64..83
}

static void drawScene() {
  fillRect(0, 0, LCD_W, LCD_H, C_SKY);     // clear the random-power-up frame memory
  fillRect(0, 120, LCD_W, 40, C_GRASS);    // grass strip

  // cat, orange
  fillRect(50, 34, 8, 12, C_ORANGE);       // left ear
  fillRect(78, 34, 8, 12, C_ORANGE);       // right ear
  fillRect(50, 44, 36, 36, C_ORANGE);      // head
  fillRect(48, 78, 40, 42, C_ORANGE);      // body

  // face details
  fillRect(56, 56, 6, 8, C_EYE);           // left eye
  fillRect(74, 56, 6, 8, C_EYE);           // right eye
  fillRect(63, 68, 4, 4, C_NOSE);          // nose

  // cream front paws, sitting on the bottom of the body
  fillRect(50, 112, 10, 8, C_CREAM);
  fillRect(76, 112, 10, 8, C_CREAM);

  drawTextHi();
}

// Common bounding box of both tail poses: sky only (cat body ends at x=87,
// grass starts at y=120), so erasing it never touches the cat or the grass.
static void drawTail(uint8_t phase) {
  fillRect(88, 72, 20, 44, C_SKY);
  if (phase == 0) {
    fillRect(88, 100, 20, 10, C_ORANGE);   // tail stretched out to the right
  } else {
    fillRect(88, 74, 12, 40, C_ORANGE);    // tail raised upright
  }
}

// ---------------------------------------------------------------- setup / loop
void setup() {
  Serial.begin(115200);

  SPI.begin();
  SPI.beginTransaction(SPISettings(8000000, MSBFIRST, SPI_MODE0));

  lcdInit();
  drawScene();

  Serial.println("pixel pet ready");
}

void loop() {
  static unsigned long lastFlip = 0;
  static uint8_t phase = 0;

  unsigned long now = millis();
  if (now - lastFlip >= 500UL) {
    lastFlip += 500UL;
    if (now - lastFlip >= 500UL) {   // catch up if we ever fall far behind
      lastFlip = now;
    }
    phase ^= 1;
    drawTail(phase);
    Serial.print("tail ");
    Serial.println(phase ? "up" : "side");
  }
}
